import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {
                "BLOCK_M": 32,
                "BLOCK_N": 32,
                "BLOCK_K": 16,
                "GROUP_M": 8,
                "grf_mode": "256",
            },
        ),
    ],
    key=["C_out", "K_FUSED"],
)
@triton.jit
def _conv3d_fused_k(
    x_ptr,
    w_ptr,
    y_ptr,
    N_batch,
    C_out,
    OD,
    OH,
    OW,
    sxn,
    sxd,
    sxh,
    sxw,
    syn,
    syd,
    syh,
    syw,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_M: tl.constexpr,
    KD: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    C_IN: tl.constexpr,
    K_FUSED: tl.constexpr,
    grf_mode: tl.constexpr,
):
    pid = tl.program_id(0)
    M_total = N_batch * OD * OH * OW
    num_pid_m = tl.cdiv(M_total, BLOCK_M)
    num_pid_n = tl.cdiv(C_out, BLOCK_N)
    num_pid_in_group = GROUP_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_M)
    pid_in_group = pid % num_pid_in_group
    pid_m = first_pid_m + (pid_in_group % group_size_m)
    pid_n = pid_in_group // group_size_m

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_k = tl.arange(0, BLOCK_K)

    ohw = OH * OW
    odhw = OD * ohw
    n_idx = offs_m // odhw
    rem = offs_m % odhw
    od_idx = rem // ohw
    rem2 = rem % ohw
    oh_idx = rem2 // OW
    ow_idx = rem2 % OW

    mask_m = offs_m < M_total

    x_spatial_base = (
        x_ptr + n_idx.to(tl.int64) * sxn + od_idx * sxd + oh_idx * sxh + ow_idx * sxw
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    w_bp = tl.make_block_ptr(
        base=w_ptr,
        shape=(K_FUSED, C_out),
        strides=(C_out, 1),
        offsets=(0, pid_n * BLOCK_N),
        block_shape=(BLOCK_K, BLOCK_N),
        order=(1, 0),
    )

    for k0 in range(0, K_FUSED, BLOCK_K):
        k_idx = k0 + offs_k
        c_off = k_idx % C_IN
        spatial_idx = k_idx // C_IN
        kw_off = spatial_idx % KW
        kh_off = (spatial_idx // KW) % KH
        kd_off = spatial_idx // (KW * KH)
        k_input_off = kd_off * sxd + kh_off * sxh + kw_off * sxw + c_off

        x_tile = tl.load(
            x_spatial_base[:, None] + k_input_off[None, :],
            mask=mask_m[:, None] & (k_idx[None, :] < K_FUSED),
            other=0.0,
        )
        w_tile = tl.load(w_bp, boundary_check=(0, 1), padding_option="zero")
        acc = tl.dot(x_tile, w_tile, acc)
        w_bp = tl.advance(w_bp, (BLOCK_K, 0))

    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    mask_n = offs_n < C_out
    y_ptrs = (
        y_ptr + n_idx.to(tl.int64) * syn + od_idx * syd + oh_idx * syh + ow_idx * syw
    )
    tl.store(
        y_ptrs[:, None] + offs_n[None, :],
        acc.to(tl.float16),
        mask=mask_m[:, None] & mask_n[None, :],
    )


class Model(nn.Module):
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride=1,
        padding=0,
        dilation=1,
        groups=1,
        bias=False,
    ):
        super(Model, self).__init__()
        ks = (kernel_size, kernel_size, 1)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, *ks))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in = in_channels * ks[0] * ks[1] * ks[2]
            bound = 1 / fan_in**0.5
            nn.init.uniform_(self.bias, -bound, bound)
        self._packed = False

    def _pack_weights(self):
        w = self.weight.data
        C_out, C_in, KD, KH, KW = w.shape
        self.w_fused = (
            w.permute(2, 3, 4, 1, 0)
            .reshape(KD * KH * KW * C_in, C_out)
            .contiguous()
            .to(dtype=torch.float16)
        )
        self._KD, self._KH, self._KW = KD, KH, KW
        self._C_in = C_in
        self._C_out = C_out
        self._K_fused = KD * KH * KW * C_in
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        B, C_in, D_in, H_in, W_in = x.shape
        KD, KH, KW = self._KD, self._KH, self._KW
        C_out = self._C_out
        OD = D_in - KD + 1
        OH = H_in - KH + 1
        OW = W_in - KW + 1

        x_fp16 = x.to(dtype=torch.float16)
        x_cl = x_fp16.contiguous(memory_format=torch.channels_last_3d)
        y = torch.empty(
            B,
            C_out,
            OD,
            OH,
            OW,
            device=x.device,
            dtype=torch.float16,
            memory_format=torch.channels_last_3d,
        )

        sx = x_cl.stride()
        sy = y.stride()

        M_total = B * OD * OH * OW
        grid = lambda meta: (
            triton.cdiv(M_total, meta["BLOCK_M"]) * triton.cdiv(C_out, meta["BLOCK_N"]),
        )

        _conv3d_fused_k[grid](
            x_cl,
            self.w_fused,
            y,
            B,
            C_out,
            OD,
            OH,
            OW,
            sx[0],
            sx[2],
            sx[3],
            sx[4],
            sy[0],
            sy[2],
            sy[3],
            sy[4],
            KD=KD,
            KH=KH,
            KW=KW,
            C_IN=C_in,
            K_FUSED=self._K_fused,
        )

        if self.bias is not None:
            y = y + self.bias.view(1, -1, 1, 1, 1)
        return y


